//! 🧪️ Original Work and Source fund each real scalar equality page.
use semio_framework_value_native_slice_equality::{RetainedSliceEquality,RetainedCloneGrant,RetainedCloneStep,RetainedCloneProgress,RetainedWorkOutcome,RetainedWorkPoll,OriginalEffectReply};
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
use semio_framework_value_testing_allocator::observe_retirement_allocations;

#[test]
fn same_source_funds_original_neutral_work_vectors(){
 let rows:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/⛽️work.json")).unwrap();
 for row in rows.as_array().unwrap(){let left:Vec<u8>=row["left"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let right:Vec<u8>=row["right"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let maximum=row["maximumWork"].as_u64().unwrap();let body=row["payloadBodyBytes"].as_u64().unwrap()as usize;let mut cursor=RetainedSliceEquality::new();let demand=cursor.demand(&left,&right,body,maximum).unwrap();let quoted=cursor.work_demand(&left,&right,body,maximum).unwrap();let stock=RetainedCloneGrant{maximum_items:2,maximum_copy_bytes:demand.copy_bytes.checked_mul(2).unwrap(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let mut bank=EffectBank::new(Wallet::new(stock,maximum+1));let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:demand.depth};let mut actual_source=None;
  for denied in [true,false]{let chosen=if denied{RetainedCloneGrant{maximum_items:0,..grant}}else{grant};let ((poll,actual),heap)=observe_retirement_allocations(||bank.run_with_source(chosen,maximum,|effect,turn|{assert_eq!(effect.work_source_turn(),Some(turn.identity()));if let Some(previous)=actual_source{assert_eq!(previous,turn.identity())}else{actual_source=Some(turn.identity())}let before=effect.performed_work();let mut slot=None;let reply=OriginalEffectReply::borrow(&mut slot).unwrap();drop(cursor.advance_into(&left,&right,body,maximum,effect,reply).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:slot.take().unwrap(),work:effect.performed_work()-before})}));assert_eq!(actual,None);assert_eq!(heap,(0,0));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native scalar comparison remained pending")};let step:RetainedCloneStep=turn.result.unwrap();assert!(step.progress().fits(chosen));if denied{assert_eq!(turn.work,0);assert_eq!(step.progress(),RetainedCloneProgress::default());assert!(!cursor.ready())}else{assert!(turn.work<=u128::from(quoted));assert_eq!(turn.work,u128::from(row["work"].as_u64().unwrap()));assert_eq!(cursor.ready(),row["ready"].as_bool().unwrap());assert_eq!(cursor.equal(),row["equal"].as_bool());}assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),chosen,heap);}
 }
}

/// 🧵️ An overfunded parent cannot change the selected logical equality page.
#[test]fn original_logical_work_request_survives_overfunded_parent(){let rows:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/⛽️work.json")).unwrap();let row=rows.as_array().unwrap().iter().find(|row|row["maximumWork"]==2).unwrap();let left:Vec<u8>=row["left"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let right:Vec<u8>=row["right"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as u8).collect();let original=(left.as_ptr(),right.as_ptr());let requested=row["maximumWork"].as_u64().unwrap();let body=row["payloadBodyBytes"].as_u64().unwrap()as usize;let mut cursor=RetainedSliceEquality::new();let demand=cursor.demand(&left,&right,body,requested).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:demand.depth};let mut bank=EffectBank::new(Wallet::new(grant,10));let mut reply=None;let((poll,actual),heap)=observe_retirement_allocations(||bank.run_with_source(grant,10,|effect,turn|{assert_eq!(effect.work_source_turn(),Some(turn.identity()));let before=effect.performed_work();drop(cursor.advance_into(&left,&right,body,requested,effect,OriginalEffectReply::borrow(&mut reply).unwrap()).unwrap());RetainedWorkPoll::Complete(RetainedWorkOutcome{result:reply.take().unwrap(),work:effect.performed_work()-before})}));assert_eq!(actual,None);assert_eq!(heap,(0,0));let RetainedWorkPoll::Complete(turn)=poll else{panic!("native equality page pending")};assert_eq!(turn.work,u128::from(row["work"].as_u64().unwrap()));let step=turn.result.unwrap();assert_eq!(cursor.ready(),row["ready"].as_bool().unwrap());assert_eq!(cursor.equal(),row["equal"].as_bool());assert_eq!((left.as_ptr(),right.as_ptr()),original);assert_ne!(bank.take_admitted(),Some(false));bank.post(step.progress(),grant,heap);}
